import { api } from './client'
import { pageParams, type Page, type PageRequest } from './paging'

/** The endpoints of warehouse items in Warehouse Items, Images, and Products of docs/api/api-design.md. */

export interface Item {
  id: number
  /** 8 characters from A-Z and 0-9, generated by the server. */
  sku: string
  name: string
  /** The address of the picture, or null when the item has none. Loaded without a token. */
  imageUrl: string | null
  availableQuantity: number
  /** Whether the product of the item is on sale. An item on sale cannot be edited. */
  listed: boolean
}

export function listItems(search: string, page: PageRequest): Promise<Page<Item>> {
  const params = new URLSearchParams()
  const part = search.trim()
  if (part) params.append('search', part)
  pageParams(params, page)
  const query = params.toString()
  return api<Page<Item>>(query ? `/items?${query}` : '/items')
}

/** A stored picture: `path` is sent with the item, `url` shows it. */
export interface StoredImage {
  path: string
  url: string
}

/** Stores a picture by itself, before the item that will use it is saved. */
export function uploadItemImage(file: File): Promise<StoredImage> {
  const form = new FormData()
  form.append('file', file)
  return api<StoredImage>('/item-images', { method: 'POST', body: form })
}

/**
 * Adds an item. `startingQuantity` is left out when the field is blank (the server then starts at 0).
 * The SKU is generated by the server and comes back with the item.
 */
export function createItem(name: string, imagePath: string | null, startingQuantity: number | null): Promise<Item> {
  const body: Record<string, unknown> = { name, imagePath }
  if (startingQuantity !== null) body.startingQuantity = startingQuantity
  return api<Item>('/items', { method: 'POST', body })
}

/** Saves the whole editable state of an item: a null `imagePath` removes its picture. */
export function editItem(id: number, name: string, imagePath: string | null): Promise<Item> {
  return api<Item>(`/items/${id}`, { method: 'PUT', body: { name, imagePath } })
}

const IMAGE_URL_PREFIX = '/api/v1/images/'

/** The stored path of a picture from its address, to send an unchanged picture back with an edit. */
export function imagePathOf(url: string | null): string | null {
  return url && url.startsWith(IMAGE_URL_PREFIX) ? url.slice(IMAGE_URL_PREFIX.length) : null
}

/** The three manual stock changes; each answers with the item and its new stock. */
export type StockChange = 'STOCK_IN' | 'WRITE_OFF' | 'CORRECTION'

const STOCK_CHANGE_PATH: Record<StockChange, string> = { STOCK_IN: 'stock-in', WRITE_OFF: 'write-off', CORRECTION: 'correction' }

/**
 * A stock-in or a write-off takes the quantity moved; a correction takes the number that was counted and
 * the stock the person saw (`expectedQuantity`), which the server compares under its lock.
 */
export function changeStock(id: number, change: StockChange, quantity: number, reason: string, expectedQuantity: number): Promise<Item> {
  const body: Record<string, unknown> = { quantity, reason }
  if (change === 'CORRECTION') body.expectedQuantity = expectedQuantity
  return api<Item>(`/items/${id}/${STOCK_CHANGE_PATH[change]}`, { method: 'POST', body })
}

/** The deletion is soft and cannot be undone: the item leaves the list, and its product is delisted. */
export function deleteItem(id: number): Promise<void> {
  return api(`/items/${id}`, { method: 'DELETE' })
}
